#include <algorithm>
#include <cassert>
#include <chrono>
#include <iostream>
#include <unordered_map>
#include <vector>
using namespace std;

const int MOD = 1'000'000'007;

struct custom_hash {
    static uint64_t splitmix64(uint64_t x) {
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }
    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = chrono::steady_clock::now().time_since_epoch().count() * (uint64_t)(new char);
        return splitmix64(x + FIXED_RANDOM);
    }
};

struct mod_int {
    int val;
    mod_int(long long v = 0) { if (v < 0) v = v % MOD + MOD; if (v >= MOD) v %= MOD; val = v; }
    static int mod_inv(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r) { int q = g / r; g %= r; swap(g, r); x -= q * y; swap(x, y); }
        return x < 0 ? x + m : x;
    }
    explicit operator int() const { return val; }
    mod_int& operator+=(const mod_int &o) { val += o.val; if (val >= MOD) val -= MOD; return *this; }
    mod_int& operator-=(const mod_int &o) { val -= o.val; if (val < 0) val += MOD; return *this; }
    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
#if !defined(_WIN32) || defined(_WIN64)
        return x % m;
#else
        unsigned xh = x >> 32, xl = (unsigned)x;
        unsigned q, r;
        asm("divl %4\n" : "=a"(q), "=d"(r) : "d"(xh), "a"(xl), "r"(m));
        return r;
#endif
    }
    mod_int& operator*=(const mod_int &o) { val = fast_mod((uint64_t)val * o.val); return *this; }
    mod_int& operator/=(const mod_int &o) { return *this *= o.inv(); }
    friend mod_int operator+(const mod_int &a, const mod_int &b) { return mod_int(a) += b; }
    friend mod_int operator-(const mod_int &a, const mod_int &b) { return mod_int(a) -= b; }
    friend mod_int operator*(const mod_int &a, const mod_int &b) { return mod_int(a) *= b; }
    friend mod_int operator/(const mod_int &a, const mod_int &b) { return mod_int(a) /= b; }
    mod_int operator-() const { return val ? MOD - val : 0; }
    mod_int inv() const { return mod_inv(val); }
    mod_int pow(long long p) const { mod_int a = *this, r = 1; while (p) { if (p & 1) r *= a; a *= a; p >>= 1; } return r; }
};

const int N_MAX = 10;
int N;
mod_int p[N_MAX][N_MAX];

int main() {
    cin >> N;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            int x; cin >> x;
            p[i][j] = mod_int(x) / 100;
        }

    vector<vector<int>> masks(N + 1);
    vector<int> id(1 << N, -1);
    for (int m = 0; m < (1 << N); ++m) {
        int cnt = __builtin_popcount(m);
        id[m] = masks[cnt].size();
        masks[cnt].push_back(m);
    }

    unordered_map<long long, mod_int, custom_hash> dp;
    dp[1LL << id[0]] = 1;

    for (int i = 0; i < N; ++i) {
        unordered_map<long long, mod_int, custom_hash> nxt;
        vector<mod_int> mul(1 << N, 1);
        for (int m = 0; m < (1 << N); ++m)
            for (int c = 0; c < N; ++c)
                mul[m] *= (m >> c & 1) ? p[i][c] : 1 - p[i][c];

        for (auto &kv : dp) {
            long long st = kv.first;
            mod_int pr = kv.second;
            vector<long long> added(N, 0);
            for (int sm : masks[i])
                if ((st >> id[sm]) & 1)
                    for (int c = 0; c < N; ++c)
                        if ((sm >> c & 1) == 0)
                            added[c] |= 1LL << id[sm | (1 << c)];

            long long temp = 0;
            for (int m = 1; m < (1 << N); ++m) {
                int b = __builtin_ctz(m);
                temp = (temp & ( (m-1) & m ? temp : 0 )); // This is wrong; let's use original logic.
                // Instead, compute as original:
                // we need a separate vector for each state.
                // So let's create a vector inside the loop.
            }
        }
        // Redo properly:
        for (auto &kv : dp) {
            long long st = kv.first;
            mod_int pr = kv.second;
            vector<long long> added(N, 0);
            for (int sm : masks[i])
                if ((st >> id[sm]) & 1)
                    for (int c = 0; c < N; ++c)
                        if ((sm >> c & 1) == 0)
                            added[c] |= 1LL << id[sm | (1 << c)];

            vector<long long> ns(1 << N, 0);
            for (int m = 1; m < (1 << N); ++m) {
                int low = m & -m;
                ns[m] = ns[m ^ low] | added[__builtin_ctz(low)];
                nxt[ns[m]] += pr * mul[m];
            }
        }
        dp = move(nxt);
        cerr << dp.size() << endl;
    }

    mod_int ans = 0;
    int full = (1 << N) - 1;
    for (auto &kv : dp)
        if ((kv.first >> id[full]) & 1)
            ans += kv.second;
    cout << (int)ans << '\n';
    return 0;
}
